import itertools

def get_valid_S(n):
    all_points = list(itertools.product(range(n), range(n)))
    valid_S = []
    def backtrack(idx, current_S):
        if idx == len(all_points):
            if len(current_S) >= 2:
                valid_S.append(set(current_S))
            return
        p = all_points[idx]
        can_include = True
        for cp in current_S:
            if max(abs(p[0]-cp[0]), abs(p[1]-cp[1])) < 2:
                can_include = False
                break
        if can_include:
            backtrack(idx + 1, current_S + [p])
        backtrack(idx + 1, current_S)
    backtrack(0, [])
    return valid_S

def check_R(R, valid_S):
    # For any S1, S2 in valid_S, S1 \Delta S2 is not a subset of R
    # This is equivalent to: for any S in valid_S, S \setminus R uniquely determines S.
    # No, the condition is: S1 \cap Q = S2 \cap Q => S1 = S2.
    # This is S1 \setminus R = S2 \setminus R => S1 = S2.
    seen = {}
    for S in valid_S:
        s_minus_R = tuple(sorted(list(S - R)))
        if s_minus_R in seen:
            return False
        seen[s_minus_R] = S
    return True

def find_max_R(n):
    valid_S = get_valid_S(n)
    all_points = list(itertools.product(range(n), range(n)))
    for r_size in range(len(all_points), -1, -1):
        for R in itertools.combinations(all_points, r_size):
            if check_R(set(R), valid_S):
                return r_size
    return 0

print(f"n=3: {find_max_R(3)}")
print(f"n=4: {find_max_R(4)}")
